class CircularQueue:
    def __init__(self, size):
        self.queue = [None] * size  # Creating a circular list with empty slots
        self.front = self.rear = -1   # Initially, both front and rear are pointing to None
        self.size = size

    def is_empty(self):
        return self.front == -1

    def is_full(self):
        return (self.rear + 1) % self.size == self.front

    def enqueue(self, data):
        if self.is_full():
            print("Queue is full")
        elif self.is_empty():
            self.front = 0
            self.rear = 0
            self.queue[self.rear] = data
        else:
            self.rear = (self.rear + 1) % self.size
            self.queue[self.rear] = data

    def dequeue(self):
        if self.is_empty():
            print("Queue is empty")
            return
        data = self.queue[self.front]
        if self.front == self.rear:
            self.front = -1
            self.rear = -1
        else:
            self.front = (self.front + 1) % self.size
        return data

    def display(self):
        if self.is_empty():
            print("Queue is empty")
            return
        print("Elements of the queue are: ", end="")
        for I in range(self.front, self.rear + 1):
            print(self.queue[i], end=" ")
        print()

