using System;

public class TreeNode {
    public int val;
    public TreeNode left, right;

    public TreeNode(int val) {
        this.val = val;
        left = right = null;
    }
}

public class BinarySearchTree {
    public TreeNode root;

    public BinarySearchTree() {
        root = null;
    }

    public void Insert(int val) {
        root = InsertRec(root, val);
    }

    // A recursive function to insert a new node with given value, recursively
    TreeNode InsertRec(TreeNode root, int val) {
        if (root == null) {
            root = new TreeNode(val);
            return root;
        }

        if (val < root.val)
            root.left = InsertRec(root.left, val);
        else if (val > root.val)
            root.right = InsertRec(root.right, val);

        return root;
    }

    public void Search(int val) {
        TreeNode currentNode = root;
        bool found = false;
        Stack<TreeNode> path = new Stack<TreeNode>();

        while ((currentNode != null) && (!found)) {
            if (val == currentNode.val) {
                Console.WriteLine("Value found: " + val);
                found = true;
            }
            else if (val < currentNode.val) {
                path.Push(currentNode);
                currentNode = currentNode.left;
            }
            else {
                path.Push(currentNode);
                currentNode = currentNode.right;
            }
        }

        if (!found) {
            Console.WriteLine("Value not found in tree.");
        }

        // Print the path to the node with the given value
        if (found) {
            Console.WriteLine("Path to node:");
            while (!path.IsEmpty()) {
                Console.Write(path.Pop().val + " ");
            }
            Console.WriteLine();
        }
    }

