        tree.Insert(30);
        tree.Insert(20);
        tree.Insert(40);
        tree.Insert(70);
        tree.Insert(60);
        tree.Insert(80);

        tree.Search(30);
        tree.Search(20);
        tree.Search(80);
        tree.Search(100);
    }
}
