2. Erstellen Sie eine neue Regel-Datei `vue-internal-hooks-status-change.js` und fügen Sie folgenden Code ein:

   ```javascript
   module.exports = {
     meta: {
       docs: {
         description: 'Enforces that lifecycle hook methods do not modify internal component state',
         category: 'Best Practices',
         recommended: true,
         extends: 'eslint:recommended',
       },
       fixable: 'code',
       schema: [],
     },

     create: function (context) {
       return {
         'VueTemplate:exit'(node) {
           const internalHooks = ['beforeCreate', 'created', 'beforeMount', 'mounted', 'beforeUpdate', 'updated', 'beforeDestroy', 'destroyed'];

           // Iterate over lifecycle hook methods and check for state modifications
           node.expression.arguments.forEach((argument) => {
             if (internalHooks.includes(argument.name.name)) {
               const parent = context.getAncestors().find((ancestor) => ancestor.type === 'Program');

               // Traverse up the AST to find method calls
               argument.traverse({
                 CallExpression: (call) => {
                   const callee = call.callee;

                   // Check if method call targets another lifecycle hook method
                   if (callee.type === 'MemberExpression' && callee.object.name === 'this' && internalHooks.includes(callee.property.name)) {
                     context.report({
                       node: callee,
                       message: 'Lifecycle hook method {{name}} should not modify internal component state.',
                       data: { name: callee.property.name },
                       fix(fixer) {
                         const parentCallExpr = call.parent;
                         const parentMemberExpr = parentCallExpr.callee;

                         return fixer.replaceText(parentMemberExpr, '()');
                       },
                     });
                   }
                 },
               });
             }
           });
         },
       };
     },
   };
   ```

3. Fügen Sie dem `.eslintrc.js`-Konfigurationsdatei Ihrer Adresse oder der globalen Konfiguration (wie beispielsweise `package.json`) folgendes hinzu:

