            new_word = word[1:]
            if not new_word:
                words[frozenset((row, col))] = word
                return
            for (row_offset, col_offset) in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                new_row = row + row_offset
                new_col = col + col_offset
                backtrack(new_row, new_col, new_word, visited)
