def get_credit_score(value, thresholds):
    # Value needs to be a numeric scalar
    assert type(value) == float or type(value) == int
    if value >= thresholds[2]:
        return 1.0
    elif value >= thresholds[1]:
        return (value - thresholds[1]) / (thresholds[2] - thresholds[1])
    else:
        return (thresholds[0] - value) / (thresholds[0] - thresholds[1])
```

