```javascript
// Set initial variables
let score = 0;
let maxQuestions = 10;

// Generate random math operation
function getRandomMathOperation() {
  const operators = ["+", "-"];
  const num1 = Math.floor(Math.random() * 11);
  const operator = operators[Math.floor(Math.random() * operators.length)];
  const num2 = operator === "+" ? num1 : Math.floor(Math.random() * (11 - num1));
  return { num1, operator, num2 };
}

// Handle user input
function handleSubmit(event) {
  event.preventDefault();

  const userAnswer = parseInt(document.querySelector("#user-answer").value);
  const mathOperation = getRandomMathOperation();

  // Check answer and increment score accordingly
  if (userAnswer === calculateAnswer(mathOperation)) {
    score++;
    if (score < maxQuestions) {
      showOperation(mathOperation);
    } else {
      alert(`You answered ${score} questions correctly! Congrats.`);
    }
  } else {
    alert(`Sorry, the correct answer for ${mathOperation.num1} ${mathOperation.operator} ${mathOperation.num2} is ${calculateAnswer(mathOperation)}.`);
  }

  document.querySelector("#user-answer").value = "";
}

// Calculates the answer for a given math operation
function calculateAnswer(mathOperation) {
  return mathOperation.operator === "+" ? mathOperation.num1 + mathOperation.num2 : mathOperation.num1 - mathOperation.num2;
}

// Generates a new math operation for display
function showOperation(mathOperation) {
  const operationElement = document.querySelector("#operation");

  operationElement.innerHTML = `${mathOperation.num1} ${mathOperation.operator} ${mathOperation.num2} = `;
}

// Setup event listener for form submission
const form = document.querySelector("form");
form.addEventListener("submit", handleSubmit);

// Start the game
showOperation(getRandomMathOperation());
```

