```javascript
// Funktion zum generieren einer zufälligen Addition/Subtraktion-Aufgabe
function generateMathProblem(difficulty = 10) {
  const num1 = Math.floor(Math.random() * (difficulty + 1));
  const num2 = Math.floor(Math.random() * (difficulty + 1));
  let problem;
  if (Math.floor(Math.random() * 2) === 0) { // 50/50 Chance auf Addition oder Subtraktion
    problem = `${num1} + ${num2}`;
  } else {
    problem = `${num1} - ${num2}`;
  }
  return { problem, answer: eval(problem) }; // eval() kann uns das Ergebnis der Rechnung liefern
}

// Funktion zum überprüfen einer Antwort und ermitteln des Punktes
function checkAnswer(userAnswer, correctAnswer) {
  if (userAnswer === correctAnswer.toString()) {
    return 1; // ein Punkt erhalten
  } else {
    return 0; // keine Punkte erhalten
  }
}

// Variablen zum Spielverlauf
let score = 0;
let currentQuestion = null;

// Funktion zum Starten des Spiels
function startGame(difficulty) {
  const questions = [];
  for (let I = 0; I < 10; i++) { // zehn Fragen pro Runde
    const mathProblem = generateMathProblem(difficulty);
    questions.push(mathProblem);
  }
  playRound(difficulty, questions);
}

// Funktion zum darauffolgenden Spielabschnitt
function playRound(difficulty, questions) {
  if (!currentQuestion) {
    currentQuestion = questions.pop(); // Last Question
  }

  if (questions.length === 0) {
    endRound();
    return;
  }

  const { problem, answer } = currentQuestion;

  // User-Input-Anforderung
  const questionElement = document.getElementById('question');
  questionElement.innerHTML = problem;

  const answerInputElement = document.getElementById('user-answer');
  answerInputElement.value = '';

  answerInputElement.addEventListener('keyup', (event) => {
    if (event.key === 'Enter') { // Submit on Enter-Press
      const userAnswer = Number(answerInputElement.value);

      if (userAnswer === answer) {
        score++;
      }

      currentQuestion = questions.pop();
      if (!currentQuestion) {
        endRound();
      } else {
        questionElement.innerHTML = currentQuestion.problem;
        answerInputElement.value = '';
      }
    }
  });
}

// Funktion zum abschließen des Spielabschnitts
function endRound() {
  const resultElement = document.getElementById('result');
  resultElement.innerHTML = `Score: ${score}`;
  score = 0;
  currentQuestion = null;

  // Starten des nächsten Spiels, falls gewünscht:
  const startButtonElement = document.getElementById('start-button');
  startButtonElement.disabled = false;
  startButtonElement.addEventListener('click', () => {
    startGame(difficulty);
    startButtonElement.disabled = true;
  });
}

// HTML-Elemente für das Spiel
const questionElement = document.getElementById('question');
const resultElement = document.getElementById('result');
const startButtonElement = document.getElementById('start-button');

startButtonElement.disabled = false;
startButtonElement.addEventListener('click', () => {
  startGame(10); // Starten des Spiels mit Schwierigkeitsgrad 10
  startButtonElement.disabled = true;
});
```

