// Array von Zahlen für Rechenaufgaben
const numbers = [...Array(10)].map((_, i) => i + 1);

// Spiel-Funktion
function startGame() {
  // Setze Punkte als Variablen
  const scoreElement = document.querySelector('.score-count');
  let score = 0;

  // Klicke auf den Absenden-Button
  document.querySelector('.submit').addEventListener('click', () => {
    // Hole die Eingabe und die Frage als Strings
    const inputElement = document.querySelector('.answer');
    const input = +inputElement.value;
    const questionElement = document.querySelector('.question');
    const question = questionElement.textContent;

    // Prüfe ob die Antwort richtig ist
    if (input === calculate(question)) {
      // Steige um 1 Punkt auf
      score++;
      // Zeige die neue Punkteanzahl in der UI
      scoreElement.textContent = score;
      // Erzeuge eine neue Frage
      createQuestion();
    } else {
      // Zeige eine Nachricht, dass die Antwort falsch ist
      inputElement.setCustomValidity('Leider falsch. Bitte versuche es erneut.');
      inputElement.reportValidity();
      inputElement.setCustomValidity('');
    }

    // Aktualisiere die Eingabefelder
    inputElement.value = '';
    inputElement.blur();
  });

  // Erzeuge eine neue Frage
  createQuestion();
}

// Erzeuge eine neue Frage
function createQuestion() {
  // Hole den Zähler für die Anzahl der Fragen
  const counterElement = document.querySelector('.questions');
  const counter = +counterElement.textContent;

  // Erzeuge eine neue Frage
  const questionElement = document.querySelector('.question');
  let operation = Math.random() < 0.5 ? '+' : '-';
  const firstNumber = Math.floor(Math.random() * 10) + 1;
  const secondNumber = Math.floor(Math.random() * 10) + 1;
  const equation = `${firstNumber} ${operation} ${secondNumber}`;

  questionElement.textContent = equation;

  // Zähle die Fragen hoch
  counterElement.textContent = counter + 1;
}

// Rechen-Funktion für die generierte Gleichung
function calculate(equation) {
  const numbers = equation.split(' ').map(Number);
  const a = numbers[0];
  const op = numbers[1];
  const b = numbers[2];

  if (op === '+') {
    return a + b;
  } else if (op === '-') {
    return a - b;
  }
}

// Starte das Spiel
startGame();
