// Beispiel für GIGO in C#:
int num1 = Convert.ToInt32(Console.ReadLine());
int num2 = Convert.ToInt32(Console.ReadLine());
int sum = num1 + num2;
Console.WriteLine("Die Summe ist: " + sum);
// Wenn der Benutzer nicht numerische Daten eingibt, erzeugt dieser Code einen Fehler.
// Um ​​dies zu verhindern, sollten Eingabevalidierung und -bereinigung implementiert werden:
if(int.TryParse(Console.ReadLine(), out int num1) && int.TryParse(Console.ReadLine(), out int num2)){
