    {
        Random rand = new Random();

        TravelPlan travelPlan = new TravelPlan();

        // Versuche ein Aktivitätenplan zu erstellen, indem wir zufällige Aktivitäten generieren und überprüfen, ob sie alle Anforderungen erfüllen
        for (int I = 1; I <= 7; i++)
        {
            bool done = false;
            while (!done)
            {
                DateTime date = DateTime.Today.AddDays(i * rand.Next(2, 9)); // dateday(-3, 6) zählt von minus 3 Tagen bis zu 6 Tagen zufällig

                MultiIntelligences skill = (MultiIntelligences)rand.Next(Enum.GetNames(typeof(MultiIntelligences)).Length);
