**3. Java (JWT Signing and Verification - jjwt)**

jjwt (JSON Web Token for Java) ist eine leistungsstarke, quelloffene Bibliothek von JSON Web Tokens für Java und Android, die die Erstellung, Validierung und Signaturen von JSON Web Tokens in Ihrem Code erleichtert.

```java
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import java.security.Key;
import java.util.Date;

public class SecurityToken {

    public String generateToken(String payload) throws Exception {
        Date expirationDate = new Date(System.currentTimeMillis() + 60 * 1000); // Token valid for 1 minute

        Key key = new javax.crypto.SecretKeySpec("My_Secret_Key".getBytes(), SignatureAlgorithm.HS256.getJcaName());

        return Jwts.builder()
                .claim("subject", payload)
                .setExpiration(expirationDate)
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    public boolean verifyToken(String token) throws Exception {
        try {
            Jwts.parser()
                    .setSigningKey("My_Secret_Key".getBytes())
                    .parseClaimsJws(token);

            return true;
        } catch (Exception e) {
            return false;
        }
    }

}

// Example usage:

SecurityToken tokenCreator = new SecurityToken();
String myToken = tokenCreator.generateToken("my_security_data");

System.out.println("Token: " + myToken);

if (tokenCreator.verifyToken(myToken)) {
    System.out.println("Verification successful");
} else {
    System.out.println("Verification failed");
}
``` 

