```javascript
// Paket-Installation:
// npm install openid-connect-server jsonwebtoken express

const express = require('express');
const oauth2Server = require('openid-connect-server');
const jwt = require('jsonwebtoken');

// Express-Server-Einrichtung
const app = express();
const port = 8080;

// Tokeneregenerierungs- und -verwaltungsfunktionen
const issueAccessToken = (payload, done) => {
  const accessToken = jwt.sign(payload, 'mein-sicherheitsgeheimnis');
  done(null, { accessToken });
};

const issueIdToken = (userId, done) => {
  const idTokenPayload = {
    sub: userId,
    email: 'john.doe@example.com',
    emailVerified: true,
    auth_time: Math.floor(Date.now() / 1000),
  };
  const idToken = jwt.sign(idTokenPayload, 'mein-sicherheitsgeheimnis');
  done(null, { idToken });
};

app.use(oauth2Server.middleware({
  model: {
    // Implementierung eines nutzerbezogenen Modells
  },
  grants: ['password'],
  allowBearerTokens: true,
  accessTokenLifetime: '1h',
  refreshTokenLifetime: 0, // bei dieser Option werden keine Refresh-Tokens generiert
  accessTokenSelector: issueAccessToken,
  idToken: { emit: issueIdToken },
}));

// Server-Start und -Hauptfunktion
app.listen(port, () => {
  console.log(`OpenID-Connect-Server lauft auf http://localhost:${port}/`);
});
