// Installation von `spring-security-saml`
// Gradle: `implementation 'org.springframework.security.extensions:spring-security-saml:1.0.16.RELEASE'`

import org.springframework.security.extensions.saml2.*;
import org.springframework.security.authentication.*;
import org.springframework.security.config.annotation.web.builders.*;
import org.springframework.security.config.annotation.web.configuration.*;
import javax.servlet.http.*;

// Konfiguration von Spring Security und SAML2

@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    @Bean
    public SAML2AuthenticationProvider saml2AuthenticationProvider() throws Exception {
        SAML2AuthenticationProvider provider = new SAML2AuthenticationProvider();
        provider.set CONVERT_ASSERTION_REQUESTS_TO_AUTHENTICATION_EVENTS (true);
        provider.set CONVERT_ASSERTION_RESPONSES_TO_AUTHENTICATION_EVENTS (true);
        return provider;
    }

    @Autowired
    public void configureGlobal(AuthenticationManagerBuilder auth) throws Exception {
        auth.authenticationProvider(saml2AuthenticationProvider());
    }

    @Bean
    public SAMLOptions samlOptions() {
        SAMLOptions options = new SAMLOptions();
        options.setIDPDiscoveryDocumentURL("https://example.com/saml/metadata");
        options.setSingleSignOnServiceURL("https://example.com/saml/SSO/alias/spring");
        options.setSingleLogoutServiceURL("https://example.com/saml/slo/alias/spring");
        return options;
    }

    @Override
    public void configure(WebSecurity web) throws Exception {
        web.ignoring().antMatchers("/saml/**");
    }

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http.authorizeRequests()
                .anyRequest().authenticated().saml2Login();

        http.sessionManagement()
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
                .sessionFixation().changeSessionId();

        http.saml2Login(). loginPage ("/login"). successHandler (new CustomSAML2LoginSuccessHandler()). failureHandler (new SAML2AuthenticationFailureHandler());
        http.logout().logoutUrl("/logout"). addLogoutHandler (new SAML2LogoutHandler()). deleteCookies ("SPID"). invalidateHttpSession (true). logoutSuccessUrl ("/");
    }
}
