# Example function to find and return elements in the same order as given input list
import re

def find_alphabetic_elements(input_list):
    result = []

    for item in input_list:
        # Filter only alphabetic characters and convert to lowercase for case sensitivity
        if match := re.match(r'^[a-zA-Z]+$', item):
            result.append(match.group(0).lower())

    # Sort the filtered and lowercase elements
    result.sort()

    return result

# Test with example input
