function checkUrl(url) {
  const pattern = /^https?://[^/]+/i; // Allow URLs with or without scheme and domain
  const wpLoginRegex = /\bwp-login\.php$/i;

  const urlWithScheme = url.match(pattern) ? url.match(pattern)[0] : url;
  const matches = urlWithScheme.match(wpLoginRegex);

  if (matches) {
    console.log(`The URL ${url} matches the wp-login.php pattern.`);
  } else {
    console.log(`The URL ${url} does not match the wp-login.php pattern.`);
  }
}

// Example usage:
