<?php

// Hash a password using bcrypt
function hash_password($password) {
  $cost = 12; // adjust cost depending on your requirements
  $salt = random_bytes(32);
  $password_hash = crypt($password, sprintf('$2y$%02d$', $cost) . $salt);
  return compact('salt', 'password_hash');
}

// Check if a hashed password matches a given plain-text password
function check_password($password_hash, $password) {
  $salt = $password_hash['salt'];
  $password_hash_check = crypt($password, sprintf('$2y$%02d$%s$', $password_hash['cost'], $salt));
  return ($password_hash_check === $password_hash['password_hash']);
}

