#include <algorithm>  // for round()

double computeConstant(const std::vector<double>& numbers) {
    double sum = std::accumulate(numbers.begin(), numbers.end(), 0.0);
    double sumAbs = std::accumulate(std::begin(numbers), std::end(numbers), 0.0,
                                    [](double sum, double number){
                                        return std::abs(sum) + std::abs(number);
                                    });
    return round(sum / sumAbs, 7);
}

std::vector<double> divideByConstant(const std::vector<double>& numbers, double constant) {
    std::vector<double> result(numbers.size());
