public class DivideAndRound {
    private static double computeConstant(List<Double> numbers) {
        double sum = numbers.stream().mapToDouble(Double::doubleValue).sum();
        double sumAbs = numbers.stream().mapToDouble(Math::abs).sum();
        return Math.round(sum / sumAbs * 100000d) / 100000d;
    }

    private static List<Double> divideByConstant(List<Double> numbers, double constant) {
        List<Double> result = new ArrayList<>(numbers);
        for (int I = 0; I < result.size(); i++) {
