```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.security.oauth2.config.annotation.web.configuration.EnableResourceServer;
import org.springframework.security.oauth2.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.oauth2.config.annotation.web.configuration.ResourceServerConfigurerAdapter;
import org.springframework.security.oauth2.config.annotation.web.configurers.ResourceServerSecurityConfigurer;
import org.springframework.security.oauth2.provider.authentication.TokenAuthenticationProvider;
import org.springframework.security.oauth2.provider.client.JwtAccessTokenConverter;
import org.springframework.security.oauth2.provider.client.JwtTokenServices;
import org.springframework.security.oauth2.provider.token.TokenEnhancerChain;
import org.springframework.security.oauth2.provider.token.store.JwtTokenStore;

@SpringBootApplication(scanBasePackages = "com.example")
@EnableResourceServer
@EnableWebSecurity
public class ProtectedApplication extends ResourceServerConfigurerAdapter {

    private static final Logger log = LoggerFactory.getLogger(ProtectedApplication.class);

    @Override
    public void configure(ResourceServerSecurityConfigurer resources) throws Exception {
        resources.tokenServices(tokenServices());
    }

    @Bean
    public JwtTokenServices tokenServices() {
        JwtTokenServices tokenServices = new JwtTokenServices(null);
        final TokenEnhancerChain tokenEnhancerChain = new TokenEnhancerChain();
        tokenEnhancerChain.setTokenEnhancers(Arrays.asList(tokenEnhancer(), jwtAccessTokenConverter()));
        tokenServices.setTokenEnhancer(tokenEnhancerChain);

        tokenServices.setTokenStore(jwtTokenStore());
        tokenServices.setAuthenticationManager(authenticationManager());
        tokenServices.setAccessTokenConverter(jwtAccessTokenConverter());

        return tokenServices;
    }

    @Bean
    public JwtAccessTokenConverter jwtAccessTokenConverter() {
        final JwtAccessTokenConverter converter = new JwtAccessTokenConverter();
        converter.setSigningKey("<your_secret_key_here>"); // same as the 'jwt-secret' key in the secret
        return converter;
    }

    @Bean
    public JwtTokenStore jwtTokenStore() {
        return new JwtTokenStore(tokenServices());
    }

    @Bean
    public TokenEnhancer tokenEnhancer() {
        return new DefaultTokenEnhancer();
    }

    public static void main(String[] args) {
        SpringApplication.run(ProtectedApplication.class, args);
    }
}
```

