import org.springframework.security.oauth2.config.annotation.web.configurers.AuthorizationServerSecurityConfigurer;

@Configuration
@EnableAuthorizationServer
@EnableGlobalMethodSecurity(prePostEnabled = true)
public class SecurityConfig extends AuthorizationServerConfigurerAdapter {

    @Autowired
    private JwtTokenEnhancer tokenEnhancer;

    @Autowired
    private JwtAccessTokenConverter jwtAccessTokenConverter;

    @Autowired
    private JwtTokenStore jwtTokenStore;

    @Override
    public void configure(AuthorizationServerSecurityConfigurer security) throws Exception {
        security.tokenKeyAccess("hasAuthority('RU Steak House:READ 权限')")
                .checkTokenAccess("hasAuthority('RU Steak House:READ 权限')")
                .allowFormAuthenticationForClients()
                .tokenGranter(tokenGranter());
    }

    @Override
    public void configure(HttpSecurity http) throws Exception {
        http.authorizeRequests()
                .anyRequest().authenticated()
                .and()
                .exceptionHandling().authenticationEntryPoint(authenticationEntryPoint())
                .and()
                .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS)
                .and()
                .addFilterBefore(authenticationFilter(), UsernamePasswordAuthenticationFilter.class);
    }

    @Bean
    public TokenGranter tokenGranter() {
        RefreshTokenTokenServices refreshTokenTokenServices = new RefreshTokenTokenServices(jwtTokenStore);

        DefaultTokenServices tokenServices = new DefaultTokenServices();
        tokenServices.setTokenStore(jwtTokenStore);
        tokenServices.setTokenEnhancer(tokenEnhancer);
        tokenServices.setAccessTokenConverter(jwtAccessTokenConverter);

        CompositeTokenGranter compositeTokenGranter = new CompositeTokenGrantar(
                Lists.newArrayList(
                        new AuthorizationCodeResourceDetailsTokenGranter(authenticationManager(), tokenServices),
                        new ImplicitFlowTokenGranter(authenticationManager(), tokenServices, jwtAccessTokenConverter),
                        new ClientCredentialsTokenGranter(authenticationManager(), tokenServices),
                        new ResourceOwnersImplicitFlowTokenGranter(authenticationManager(), tokenServices, jwtAccessTokenConverter),
                        new RefreshTokenTokenGranter(authenticationManager(), refreshTokenTokenServices, tokenServices)
                )
        );

        return compositeTokenGranter;
    }

    @Bean
    public TokenAuthenticationFilter authenticationFilter() throws Exception {
        return new TokenAuthenticationFilter(authenticationManager(), authenticationEntryPoint());
    }

    @Bean
    public AuthenticationEntryPoint authenticationEntryPoint() {
        return new JwtAuthenticationEntryPoint();
    }
}

```

