```java
import io.jsonwebtoken.Claims;
import org.springframework.security.core.Authentication;
import org.springframework.security.oauth2.common.OAuth2AccessToken;
import org.springframework.security.oauth2.provider.token	TokenNameEnhancer;

import java.util.Map;

public class JwtTokenEnhancer implements TokenNameEnhancer {

    @Override
    public Map<String, Object> enhance(Map<String, Object> additionalInformation, OAuth2AccessToken oAuth2AccessToken,
                                       Authentication authentication) {
        final Claims claims = (Claims) oAuth2AccessToken.getAdditionalInformation();

        String username = authentication.getName();
        claims.put("sub", username);

        return additionalInformation;
    }
}
