public class FlyingObjectCamera : MyPlayerCameraBase 
{
    private MyFlyingObject flyingObject;
    private float cameraAngle;
    private float cameraSpeed = 8f;

    public FlyingObjectCamera(MyFlyingObject flyingObject, MyPlayer player) 
        : base(player)
    {
        this.flyingObject = flyingObject;
        Resize(0.5f, flyingObject.Base.Position, flyingObject.Base.Rotation);
    }

    public override void UpdateAfterTick(float deltaGameTime)
    {
        base.UpdateAfterTick(deltaGameTime);

        // Set up smooth camera rotation
        if (InputManager.Current.IsNewKeyPress(MyControlsManager.Instance.GetKey(MyKeys.LeftAlt)))
        {
            cameraAngle += cameraSpeed * deltaGameTime;
        }
        else if (InputManager.Current.IsNewKeyPress(MyControlsManager.Instance.GetKey(MyKeys.LeftControl)))
        {
            cameraAngle -= cameraSpeed * deltaGameTime;
        }

        Rotation = Quaternion.Euler(0, (float)MathHelper.Clamp(cameraAngle, -90f, 90f), 0) * Base.Rotation;
    }
}
```

In this example, we create a new `FlyingObjectCamera` instance whenever the player mounts the flying object. The camera is positioned within the flying object, rotating smoothly based on player input.

