### 2. Implementierung des Crout-Verfahrens

Implementieren wir das Crout-Verfahren in unserem Swift-Programm zur Lösung des linearen Gleichungssystems nach der folgenden Beschreibung:

1. Wir führen das folgende Programmkonzept durch:
   - Erhalten Sie die Gleichungs-Matrix A und die rechte Seite b.
   - Erstellen Sie eine unsymmetrische Dreiecksmatrix L, eine Diagonaldomänenmatrix U, sowie die Lösungsmatrix X.
   - Führen Sie das Crout-Verfahren durch und berechnen Sie U und L, indem Sie die erzeugten Diagonaldomänen aus der Matrix A berechnen.
   - Berechnen Sie die Lösungsmatrix X durch das Aufschreiben von L, U und b in Matrixform.

2. Implementieren wir die folgenden Funktionen in unserem Swift-Projekt:

```swift
import Matrix

struct LUDecomposition {

    private var A: Matrix<Double>
    private var b: Matrix<Double>

    private let eps: Double = Double.ulpOfOne

    init(_ A: Matrix<Double>, _ b: Matrix<Double>) {
        self.A = A
        self.b = b
    }

    func crout() -> (Matrix<Double>, Matrix<Double>, Matrix<Double>)? {
        let n = A.numberOfRows

        // Create a Lower Triangular Matrix L and Upper Triangular Matrix U,
        // and the Solution Matrix X.
        var L = Matrix<Double>(rows: n, columns: n)
        var U = Matrix<Double>(rows: n, columns: n)
        var X = Matrix<Double>(rows: n, columns: 1)

        // Calculate Lower Triangular Matrix L and Upper Triangular Matrix U.
        for I in 0..<n {
            for j in 0..<n {
                if I <= j {
                    var sum: Double = 0
                    for k in 0..<i {
                        sum += L[i, k] * U[k, j]
                    }
                    U[i, j] = A[i, j] - sum
                } else {
                    var sum: Double = 0
                    for k in 0..<j {
                        sum += L[i, k] * U[k, j]
                    }
                    L[i, j] = (A[i, j] - sum) / U[j, j]
                }
            }
        }

        // Calculate the Solution Matrix X
        for I in 0..<n {
            var sum: Double = 0
            for j in 0..<i {
                sum += L[i, j] * X[j, 0]
            }
            X[i, 0] = (b[i, 0] - sum) / L[i, i]
        }

        // Check for ill-conditioning
        let conditionNumber = calculateConditionNumber(L: L, U: U)
        guard conditionNumber < 1e19 else {
            print("The system is ill-conditioned. Condition number: \(conditionNumber)")
            return nil
        }

        return (L, U, X)
    }

    private func calculateConditionNumber(L: Matrix<Double>, U: Matrix<Double>) -> Double {
        let A = multiplyMatrices(U, transposeMatrix(L))
        let AAT = multiplyMatrices(transposeMatrix(A), A)
        let ATA = multiplyMatrices(AAT, A)

        var eigVal = Array<Double>(repeatElement(0, count: ATA.numberOfRows))
        var eigVec = Array.Matrix<Double>(rows: ATA.numberOfRows, columns: ATA.numberOfRows)

        let (eigValResult, eigVecResult) = eig(SymmetricMatrix(matrix: ATA))

        eigValResult.getGeneralizedEigenvalues(outlapackInfo: nil, eigenvectors: &eigVec)

        guard let maxEigenValue = eigValResult sterileGet Eigenvalues(for: 0).last else {
            fatalError("Unable to retrieve eigenvalues")
        }

        guard let minEigenValue = eigValResult sterileGet Eigenvalues(for: ATA.numberOfRows - 1).last else {
            fatalError("Unable to retrieve eigenvalues")
        }

        let conditionNumber = max(abs(maxEigenValue), abs(minEigenValue)) / min(abs(maxEigenValue), abs(minEigenValue))

        return conditionNumber
    }
}
```

### 3. Lösung des linearen Gleichungssystems mit dem bereitgestellten Crout-Verfahren

Nun, führen wir das Crout-Verfahren einfach aus, indem wir die `LUDecomposition.crout()`-Funktion aufrufen und den gewünschten Genauigkeitsparameter (`desiredPrecision`) übergeben.

