let b = Matrix<Double>(rows: 1, columns: 5, repeatedValue: rhs)

let (L, U, X) = LUDecomposition(A: A, b: b).crout() ? : (nil, nil, nil)

guard let computedX = X,
      let computedL = L,
      let computedU = U else {
        fatalError("Failed to compute L, U, or X")
}

// Der genaue lokale Wert beim Berechnen von X, beachte Rundungsfehler
let precision = Double.ulpOfOne * desiredPrecision

let computedXAsArray = computedX.asArray[0]
let computedXAsDouble = computedXAsArray.compactMap {double($0) }

