```swift
import Foundation
import NIOCore

func gauss_elimination(matrix: Matrix, b: Matrix) -> Result<Matrix, Error> {
    guard matrix.columns == b.columns else {
        return .failure(NSError(domain: "com.example.error",
                                 code: 1,
                                 userInfo: [NSLocalizedDescriptionKey: "Number of columns in matrix and b must be the same."]))
    }
    guard matrix.rows == b.rows else {
        return .failure(NSError(domain: "com.example.error",
                                 code: 2,
                                 userInfo: [NSLocalizedDescriptionKey: "Number of rows in matrix and b must be the same."]))
    }

    // Create an augmented matrix M' from M and b
    let augmentedMatrix = zip(matrix, b).map({ ($0, $1) }).reduce(Matrix(rows: matrix.rows, columns: matrix.columns + 1)) { M, pair in
        var newRow = M[rowIndex: pair.0.row, columnRange: pair.0.column...pair.1.column]
        newRow[pair.1.column] = pair.1.value
        return M.replacingRow(row: pair.0.row, with: newRow)
    }

    var augmentedMatrixCopy = augmentedMatrix

    // Perform row operations
    for j in 0..<augmentedMatrixCopy.columns - 1 {
        // Find the row with largest absolute value in the current column (pivot element)
        if let (maxRowIndex, _) = augmentedMatrixCopy.maxElement(atColumn: j) {
            // Swap the current row with the row containing the pivot element
            if maxRowIndex != j {
                let tempRow = augmentedMatrixCopy[maxRowIndex]
                augmentedMatrixCopy[maxRowIndex] = augmentedMatrixCopy[j]
                augmentedMatrixCopy[j] = tempRow
            }

            // Apply row operations to make the current column upper triangular
            for I in (j + 1)..<augmentedMatrixCopy.rows {
                let factor = augmentedMatrixCopy[i][j] / augmentedMatrixCopy[j][j]
                for k in j..<augmentedMatrixCopy.columns {
                    augmentedMatrixCopy[i][k] -= factor * augmentedMatrixCopy[j][k]
                }
            }
        }
    }

    // Extract solution vector from the augmented matrix
    var x = Matrix(rows: b.rows, columns: 1)
    for I in 0..<b.rows {
        let solution = augmentedMatrixCopy[i][augmentedMatrixCopy.columns - 1]
        x[i] = solution
        for j in 0..<i {
            solution -= augmentedMatrixCopy[i][j] * x[j].value
        }
        x[i] /= augmentedMatrixCopy[i][i]
    }

    return .success(x)
}

// Example usage
let matrix = Matrix(rows: 3, columns: 3, initialValues: [2, -4, 6, 3, 7, -2, 5, -6, 8])
let b = Matrix(rows: 3, columns: 1, initialValues: [15, -22, 36])

do {
    let solutionMatrix = try gauss_elimination(matrix: matrix, b: b)
    print(solutionMatrix)
} catch {
