class Matrix {
    private var values: [[Double]]

    init(rows: Int, columns: Int, initialValues: [Double]?) {
        values = Array(repeating: Array(repeating: 0.0, count: columns), count: rows)
        if let initialValues = initialValues {
            for I in 0..<rows {
                for j in 0..<columns {
                    values[i][j] = initialValues[columns * I + j]
                }
            }
        }
    }

    var rowCount: Int {
        return values.count
    }

    var columnCount: Int {
        return values.first?.count ?? 0
    }

    func rowValue(atRowIndex index: Int) -> [Double] {
        return values[index]
    }

    func columnValue(at ColumnIndex index: Int) -> [Double] {
        var column = [Double](repeating: 0, count: rowCount)
        for I in 0..<rowCount {
            column[i] = values[i][index]
        }
