    }

    func value(atRow rowIndex: Int, atColumn columnIndex: Int) -> Double {
        return values[rowIndex][columnIndex]
    }

    mutating func replacingRow(row: Int, with newValues: [Double]) -> Matrix {
        var matrix = self
        matrix.values[row] = newValues
        return matrix
    }
}

extension Matrix: CustomStringConvertible {
