const DATABASE_USER = 'YOUR_DATABASE_USER';
const DATABASE_PASSWORD = 'YOUR_DATABASE_PASSWORD';

// Libraries required to connect to Cloud SQL
const {BigQuery} = require('@google-cloud/bigquery');
const {CloudSQLMySql} = require('@google-cloud/sql-proxy');

cloudsql = new CloudSQLMySql({
  keyFilename: 'PATH/TO/YOUR/key.json',
});

bigquery = new BigQuery({
  projectId: 'YOUR_PROJECT_ID',
  keyFilename: 'PATH/TO/YOUR/key.json',
});

function connectToCloudSQL() {
  return new Promise((resolve, reject) => {
    cloudsql.connect(CLOUD_SQL_CONNECTION_NAME, (err, connection) => {
      if (err) {
