        resolve(connection);
      }
    });
  });
}

function connectToBigQuery() {
  return new Promise((resolve, reject) => {
    bigquery.connect((err, connection) => {
      if (err) {
        console.error('ERROR CONNECTING TO BIGQUERY:', err);
        reject(err);
      } else {
        console.log('Connected to BigQuery successfully');
        resolve(connection);
      }
    });
  });
}

function runQuery(sql, params = null) {
