    try {
      await connectToCloudSQL();
      const client = await cloudsql.connectToQuery({
        user: DATABASE_USER,
        password: DATABASE_PASSWORD,
        database: 'YOUR_DATABASE_NAME',
      });

      const result = await client.query(sql, params);

      await client.end();

      const rows = result[0];

      const data = rows.map(row => {
        return row.map(val => val || {});
      });

      resolve(data);
    } catch (err) {
      console.error('QUERY ERROR:', err);
      reject(err);
    }
  });
}

function runBigQueryQuery(query) {
  return new Promise(async (resolve, reject) => {
    try {
      await connectToBigQuery();

      const results = await bigquery.createQueryJob({
        query: query,
      });

      const job = await results.promise();

      const rows = [];

      do {
        const info = await job.getMetadata();
        if (info.state === 'DONE') {
          const [rows] = await job.getQueryResults();
          rows.forEach(row => {
            rows.push(row);
          });
          break;
        } else if (info.state === 'RUNNING') {
          await new Promise(resolve => setTimeout(resolve, 2000));
        }
      } while (true);

      resolve(rows);
    } catch (err) {
      console.error('BIGQUERY QUERY ERROR:', err);
      reject(err);
    }
  });
}
```

