3. Schreiben Sie folgenden Code in Ihre Google App Script:

```
// First, load the MySQL driver
function loadMySQLDriver() {
  var driver = 'com.mysql.jdbc.Driver';
  var library = 'src/driver/mysql-connector-java-8.0.22.jar';
  DriveApp.getFiles().findByName(library).setTrashed(true);
  var file = DriveApp.createFile(library, Utilities.newBlob(null, 'application/java-archive', library).getBytes());
  ScriptApp.addFile(file);
  var resourcesFolder = DriveApp.getRootFolder().findFolder('resources');
  file.getParents().next().removeFile(file);
  resourcesFolder.addFile(file);
  var blob = resourcesFolder.getFilesByName(library)[0].getBlob();
  var classloader = new java.net.URLClassLoader([blob.getSource()]);
  classloader.loadClass(driver);
}

// Establish a connection to the MySQL database
function connectToMySQLDB() {
  loadMySQLDriver();

  // Connection properties
  var db_host = 'localhost'; // Replace with your MySQL server host
  var db_name = 'myDatabaseName'; // Replace with your MySQL database name
  var db_user = 'myUsername'; // Replace with your MySQL database username
  var db_pass = 'myPassword'; // Replace with your MySQL database password
  var db_port = 3306; // Default MySQL port

  var dbURL = "jdbc:mysql://"+db_host+":"+db_port+"/"+db_name;

  // Connect to the database
  var connection = java.sql.DriverManager.getConnection(dbURL, db_user, db_pass);
  // Use the connection object to perform database operations

  // Close the connection when finished
  connection.close();
}
```

