   private fun generateAnchors(): FloatArray {
       val anchorRatios = floatArrayOf(1f, 2f, 0.5f, 1f, 2f, 0.5f)
       val baseAnchor = floatArrayOf(10.f, 14.f, 23.f)
       val num_anchors = 3
       val num_layers = 3
       val scale = 4.f

       val anchors = mutableListOf<Float>()

       for (i in 0 until num_layers) {
           val base_size = baseAnchor[i].coerceAtMost(scale)
           val anchor_step = Math.round(num_anchors.toFloat() / anchorRatios.size)
           for (j in 0 until anchorRatios.size step anchor_step) {
               anchors.add(base_size * anchorRatios[j])
               anchors.add(base_size * anchorRatios[j + 1])
           }
       }

