Ein Codebeispiel für den Einsatz von Sockets in C++ mit der Standardbibliothek "sockets" ist wie folgt:

```cpp
#include <iostream>
#include <sys/socket.h>
#include <netinet/in.h>

int main() {
  int sockfd;
  // Erstellen eines sockfd zum Verbinden
  if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
    std::cerr << "Fehler beim Erstellen des Sockets" << std::endl;
    return 1;
  }

  struct sockaddr_in server_addr, client_addr;
  // Server-Adresse zuweisen
  server_addr.sin_family = AF_INET; // IPv4-Adresse
  server_addr.sin_addr.s_addr = INADDR_ANY; // IP-Adresse für lokale Netzwerk adressen
  server_addr.sin_port = htons(12345); // Portnummer

  // Binden der sockfd mit dem Server-Adressenpaar
  if (bind(sockfd, (struct sockaddr*) &server_addr,
             sizeof(server_addr)) < 0) {
    std::cerr << "Fehler beim Binden des Sockets" << std::endl;
    close(sockfd);
    return 1;
  }

  // Warten auf Verbindungsaufbau des Clients
  int client_len = sizeof(client_addr);
  int new_fd;
  if ((new_fd = accept(sockfd, (struct sockaddr*) &client_addr, &client_len)) < 0) {
    std::cerr << "Fehler beim Warten auf neue Verbindungen" << std::endl;
    close(sockfd);
    return 1;
  }

  // Datenübertragung
  char buffer[512];
  int bytes_sent, bytes_received;
  while ((bytes_received = recv(new_fd, buffer, sizeof(buffer), 0)) > 0) {
    bytes_sent = send(new_fd, buffer, bytes_received, 0);
    if (bytes_sent < 0) {
      std::cerr << "Fehler beim Versenden von Daten" << std::endl;
      close(sockfd);
      close(new_fd);
      return 1;
    }
  }

  // Schließen von sockfds
  close(new_fd);
  close(sockfd);

  return 0;
}
```

