Folgendes Beispiel erzeugt einen TCP-Socket-Klienten, der ein Nachrichtenpaar (eine Zeichenfolge) mit einem Server austauscht:

```c++
#include <iostream>
#include <string>
#include <sys/socket.h>
#include <netinet/in.h>

int main() {
    // Erstellen des Clients
    int clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket < 0) { // Error handling
        std::cerr << "Error creating socket\n";
        return 1;
    }

    // Setzen des Adressenschemas
    struct sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(1234); // Beispiel-Port
    serverAddr.sin_addr.s_addr = inet_addr("127.0.0.1"); // Ziel-IP (localhost)

    // Verbinden mit dem Server
    if (connect(clientSocket, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) { // Error handling
        std::cerr << "Error connecting to server\n";
        close(clientSocket);
        return 1;
    }

    // Nachrichten vom Client senden und empfangen
    std::string message1 = "Hello, server!";
    send(clientSocket, message1.data(), message1.size(), 0); // Zeichenfolge als Binärdaten senden

    char buffer[1024]; // Puffer für die empfangene Nachricht
    int bytesReceived = recv(clientSocket, buffer, 1024, 0); // Nachricht empfangen
    std::string message2(buffer, bytesReceived); // Puffer in Zeichenfolge konvertieren

    std::cout << "Sent: " << message1 << std::endl;
    std::cout << "Received: " << message2 << std::endl;

    // Verbindungsbeendigung
    close(clientSocket);

    return 0;
}
``` 

